import json
import re
from docx import Document

TEMPLATE_PATH = '/root/offer_letter_template.docx'
DATA_PATH = '/root/employee_data.json'
OUTPUT_PATH = '/root/offer_letter_filled.docx'

with open(DATA_PATH, 'r') as f:
    data = json.load(f)

# Normalize keys to strings (in case of non-str values)
data = {str(k): v for k, v in data.items()}

condition_key = 'RELOCATION'
should_include = str(data.get('RELOCATION_PACKAGE', '')).strip().lower() == 'yes'

start_marker = '{{IF_' + condition_key + '}}'
end_marker = '{{END_IF_' + condition_key + '}}'

placeholder_pattern = re.compile(r'\{\{([A-Z0-9_]+)\}\}')


def set_paragraph_text(paragraph, new_text):
    runs = paragraph.runs
    if runs:
        runs[0].text = new_text
        for run in runs[1:]:
            run.text = ''
    else:
        paragraph.add_run(new_text)


def remove_paragraph(paragraph):
    p = paragraph._element
    p.getparent().remove(p)
    paragraph._p = paragraph._element = None


def process_conditionals_in_paragraphs(paragraphs, should_include):
    inside = False
    to_remove = []

    for para in paragraphs:
        text = para.text
        if not text:
            if inside and not should_include:
                to_remove.append(para)
            continue

        has_start = start_marker in text
        has_end = end_marker in text

        if has_start and has_end:
            if should_include:
                new_text = text.replace(start_marker, '').replace(end_marker, '')
                set_paragraph_text(para, new_text)
            else:
                new_text = re.sub(re.escape(start_marker) + r'.*?' + re.escape(end_marker), '', text)
                if new_text.strip():
                    set_paragraph_text(para, new_text)
                else:
                    to_remove.append(para)
            continue

        if has_start:
            if should_include:
                new_text = text.replace(start_marker, '')
                set_paragraph_text(para, new_text)
                inside = True
            else:
                # Remove marker and any following text in this paragraph
                before = text.split(start_marker, 1)[0]
                if before.strip():
                    set_paragraph_text(para, before)
                else:
                    to_remove.append(para)
                inside = True
            continue

        if has_end:
            if should_include:
                new_text = text.replace(end_marker, '')
                set_paragraph_text(para, new_text)
                inside = False
            else:
                after = text.split(end_marker, 1)[1]
                if after.strip():
                    set_paragraph_text(para, after)
                else:
                    to_remove.append(para)
                inside = False
            continue

        if inside and not should_include:
            to_remove.append(para)

    for para in to_remove:
        remove_paragraph(para)


def replace_placeholders_in_paragraph(para, data):
    text = para.text
    if not text:
        return
    matches = placeholder_pattern.findall(text)
    if not matches:
        return
    new_text = text
    for key in matches:
        placeholder = '{{' + key + '}}'
        if key in data:
            new_text = new_text.replace(placeholder, str(data[key]))
    if new_text != text:
        set_paragraph_text(para, new_text)


def process_container(container):
    # Conditionals first
    process_conditionals_in_paragraphs(container.paragraphs, should_include)

    # Replace placeholders in paragraphs
    for para in container.paragraphs:
        replace_placeholders_in_paragraph(para, data)

    # Recurse into tables
    for table in container.tables:
        process_table(table)


def process_table(table):
    for row in table.rows:
        for cell in row.cells:
            process_container(cell)


doc = Document(TEMPLATE_PATH)

# Main document body
process_container(doc)

# Headers/footers
for section in doc.sections:
    process_container(section.header)
    process_container(section.footer)

# Save result

doc.save(OUTPUT_PATH)

print('Saved', OUTPUT_PATH)
